-- 540+ contacts for agency account
-- Includes 117 subaccount-named contacts + 423+ generic leads
-- Run in Supabase SQL editor

DO $$
DECLARE
  v_account_id uuid := 'da99b768-79dd-48f8-af86-abf95e61a69f';
BEGIN

-- BATCH 1: 117 named contacts (subaccount names + realistic real estate brokerages)

-- BATCH 2: 423 lead contacts (varied names, sources, companies)
SELECT
  v_account_id,
  first_name,
  last_name,
  lower(first_name) || '.' || lower(last_name) || seq || '@' || domain,
  '+1415555' || lpad((1000 + seq)::text, 4, '0'),
  company,
  CASE WHEN seq % 3 = 0 THEN 'customer' ELSE 'lead' END,
  (ARRAY['cold_email','cold_email','cold_email','instagram','referral'])[1 + (seq % 5)],
  now() - (seq * interval '1 day'),
  now() - (seq * interval '12 hours')
FROM (
  SELECT
    seq,
    (ARRAY['Liam','Noah','Oliver','Elijah','James','Aiden','Lucas','Mason','Ethan','Logan','Jackson','Sebastian','Jack','Owen','Theo','Caleb','Ryan','Nathan','Dylan','Henry','Wyatt','Hudson','Gabriel','Julian','Grayson','Lincoln','Eli','Connor','Landon','Isaiah','Aaron','Thomas','Luke','Hayes','Miles','Kingston','Jaxon','Jace','Kayden','Brandon','Jameson','Kyle','Blake','Colton','Brooks','Reid','Michael','Cole','Ezra','Chase','Luca','Beckett','Brayden','Bryson','Cruz','Damian','Davis','Griffin','Jordan','Jose','Ian','Parker','Zachary','Caden','Hunter','Cameron','Tucker','Easton','Cooper','Bentley','Xavier','Roman','Sawyer','Silas','Declan','Legend','Rowan','Jaxson','Emmett','Finley','Harrison','Ryder','Adriel','Kaden','Jasper','Cash','Ezekiel','Felix','Tobias','Xander','Remy','Zane','Marcus','Archer','Arthur','Max','Maxwell','Micah','Nolan','Preston','River','Rylan','Tatum','Waylon'])[1 + (seq % 100)] AS first_name,
    (ARRAY['Smith','Johnson','Williams','Brown','Jones','Garcia','Miller','Davis','Martinez','Wilson','Anderson','Taylor','Thomas','Hernandez','Moore','Martin','Jackson','Thompson','White','Lopez','Lee','Gonzalez','Harris','Clark','Lewis','Robinson','Walker','Perez','Hall','Young','Allen','Sanchez','Wright','King','Scott','Green','Baker','Adams','Nelson','Hill','Ramirez','Campbell','Mitchell','Roberts','Carter','Phillips','Evans','Turner','Torres','Parker','Collins','Edwards','Stewart','Flores','Morris','Nguyen','Murphy','Rivera','Cook','Rogers','Morgan','Peterson','Cooper','Reed','Bailey','Bell','Gomez','Kelly','Howard','Ward','Cox','Diaz','Richardson','Wood','Watson','Brooks','Bennett','Gray','James','Reyes','Cruz','Hughes','Price','Myers','Long','Foster','Sanders','Ross','Morales','Powell','Sullivan','Russell','Ortiz','Jenkins','Gutierrez','Perry','Butler','Barnes','Fisher'])[1 + (seq % 100)] AS last_name,
    (ARRAY['remax.com','kwrealty.com','coldwellbanker.com','compass.com','sothebysrealty.com','bhhs.com','century21.com','exprealty.com','redfin.com','zillow.com','realtor.com','gmail.com','yahoo.com','outlook.com'])[1 + (seq % 14)] AS domain,
    (ARRAY['RE/MAX','Keller Williams','Coldwell Banker','Compass','Sotheby''s Realty','Berkshire Hathaway','Century 21','eXp Realty','Redfin','Engel & Völkers','Douglas Elliman','Howard Hanna','Long & Foster','Weichert Realtors'])[1 + (seq % 14)] AS company
  FROM generate_series(1, 423) AS seq
) AS data;

RAISE NOTICE 'Contacts inserted: 117 named + 423 generated = 540 total';
END $$;
